import { Controller, Get, Post, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const STATEMENT_TYPES = ['잔액시산표', '일·월계표', '재무상태표', '손익계산서'];
const USE_YN = ['사용', '미사용'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function isBlank(v: unknown): boolean {
  return v === undefined || v === null || (typeof v === 'string' && v.trim() === '');
}

function isIntegerValue(v: unknown): boolean {
  if (typeof v === 'number') {
    return Number.isInteger(v);
  }
  return typeof v === 'string' && /^-?[0-9]+$/.test(v.trim());
}

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function pagingOf(query: Record<string, unknown>): { page: number; size: number } {
  let page = 0;
  let size = DEFAULT_SIZE;
  if (!isBlank(query['page'])) {
    if (!isIntegerValue(query['page']) || Number(query['page']) < 0) {
      throw invalid('page는 0 이상의 정수여야 합니다.');
    }
    page = Number(query['page']);
  }
  if (!isBlank(query['size'])) {
    if (!isIntegerValue(query['size']) || Number(query['size']) < 1) {
      throw invalid('size는 1 이상의 정수여야 합니다.');
    }
    size = Math.min(Number(query['size']), MAX_SIZE);
  }
  return { page, size };
}

@Controller('api/v1')
export class FnSfr00602Controller {
  @Post('/financial-statement-forms')
  @HttpCode(200)
  async createFinancialStatementForm(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    if (
      isBlank(data['statementType']) ||
      isBlank(data['accountItemId']) ||
      isBlank(data['itemName']) ||
      isBlank(data['useYn'])
    ) {
      throw new ApiError(422, 'FORM_REQUIRED_MISSING', '재무제표 종류, 계정과목, 항목명, 사용 여부는 필수입니다.');
    }
    if (!STATEMENT_TYPES.includes(String(data['statementType']))) {
      throw invalid('재무제표 종류가 올바르지 않습니다.');
    }
    if (!USE_YN.includes(String(data['useYn']))) {
      throw invalid('사용 여부가 올바르지 않습니다.');
    }
    if (!isIntegerValue(data['accountItemId'])) {
      throw invalid('계정과목 형식이 올바르지 않습니다.');
    }
    if (String(data['itemName']).length > 200) {
      throw invalid('항목명은 200자 이하여야 합니다.');
    }
    if (!isBlank(data['sortOrder']) && !isIntegerValue(data['sortOrder'])) {
      throw invalid('표시 순서는 정수여야 합니다.');
    }
    const sortOrder = isBlank(data['sortOrder']) ? null : String(data['sortOrder']).trim();
    return transaction(async (db) => {
      const accounts = await db.query(
        'SELECT account_item_id FROM account_item WHERE account_item_id = CAST(:accountItemId AS bigint)',
        { accountItemId: String(data['accountItemId']).trim() },
      );
      if (accounts.length === 0) {
        throw new ApiError(404, 'ACCOUNT_ITEM_NOT_FOUND', '등록되지 않은 계정과목입니다.');
      }
      const dup = await db.query(
        'SELECT financial_statement_form_id FROM financial_statement_form WHERE statement_type = :statementType AND account_item_id = CAST(:accountItemId AS bigint)',
        { statementType: String(data['statementType']), accountItemId: String(data['accountItemId']).trim() },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'FORM_DUPLICATED', '같은 재무제표 종류에 이미 연결된 계정과목입니다.');
      }
      const rows = await db.query(
        'INSERT INTO financial_statement_form (account_item_id, statement_type, item_name, sort_order, use_yn, created_at, updated_at) ' +
          'VALUES (CAST(:accountItemId AS bigint), :statementType, :itemName, CAST(:sortOrder AS integer), :useYn, now(), now()) ' +
          'RETURNING financial_statement_form_id AS "financialStatementFormId"',
        {
          accountItemId: String(data['accountItemId']).trim(),
          statementType: String(data['statementType']),
          itemName: String(data['itemName']),
          sortOrder,
          useYn: String(data['useYn']),
        },
      );
      return rows[0];
    });
  }

  @Get('/financial-statement-forms')
  async listFinancialStatementForms(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const { page, size } = pagingOf(query);
    let statementType: string | null = null;
    if (!isBlank(query['statementType'])) {
      statementType = String(query['statementType']);
      if (!STATEMENT_TYPES.includes(statementType)) {
        throw invalid('재무제표 종류가 올바르지 않습니다.');
      }
    }
    return transaction(async (db) => {
      const params = { statementType, size, offset: page * size };
      const items = await db.query(
        'SELECT financial_statement_form_id AS "financialStatementFormId", statement_type AS "statementType", ' +
          'account_item_id AS "accountItemId", item_name AS "itemName", sort_order AS "sortOrder", use_yn AS "useYn" ' +
          'FROM financial_statement_form ' +
          'WHERE (CAST(:statementType AS varchar) IS NULL OR statement_type = CAST(:statementType AS varchar)) ' +
          'ORDER BY statement_type, sort_order, financial_statement_form_id ' +
          'LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        params,
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM financial_statement_form ' +
          'WHERE (CAST(:statementType AS varchar) IS NULL OR statement_type = CAST(:statementType AS varchar))',
        { statementType },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/voucher-types')
  @HttpCode(200)
  async createVoucherType(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    if (
      isBlank(data['accountItemId']) ||
      isBlank(data['code']) ||
      isBlank(data['name']) ||
      isBlank(data['useYn'])
    ) {
      throw new ApiError(422, 'VOUCHER_TYPE_REQUIRED_MISSING', '계정과목, 전표유형 코드, 전표유형명, 사용 여부는 필수입니다.');
    }
    if (!isIntegerValue(data['accountItemId'])) {
      throw invalid('계정과목 형식이 올바르지 않습니다.');
    }
    if (!USE_YN.includes(String(data['useYn']))) {
      throw invalid('사용 여부가 올바르지 않습니다.');
    }
    if (String(data['code']).length > 20) {
      throw invalid('전표유형 코드는 20자 이하여야 합니다.');
    }
    if (String(data['name']).length > 100) {
      throw invalid('전표유형명은 100자 이하여야 합니다.');
    }
    const autoJournalType = isBlank(data['autoJournalType']) ? null : String(data['autoJournalType']);
    if (autoJournalType !== null && autoJournalType.length > 100) {
      throw invalid('자동분개 유형은 100자 이하여야 합니다.');
    }
    return transaction(async (db) => {
      const accounts = await db.query(
        'SELECT account_item_id FROM account_item WHERE account_item_id = CAST(:accountItemId AS bigint)',
        { accountItemId: String(data['accountItemId']).trim() },
      );
      if (accounts.length === 0) {
        throw new ApiError(404, 'ACCOUNT_ITEM_NOT_FOUND', '등록되지 않은 계정과목입니다.');
      }
      const dup = await db.query('SELECT voucher_type_id FROM voucher_type WHERE code = :code', {
        code: String(data['code']),
      });
      if (dup.length > 0) {
        throw new ApiError(409, 'VOUCHER_TYPE_CODE_DUPLICATED', '이미 사용 중인 전표유형 코드입니다.');
      }
      const rows = await db.query(
        'INSERT INTO voucher_type (account_item_id, code, name, auto_journal_type, use_yn, created_at, updated_at) ' +
          'VALUES (CAST(:accountItemId AS bigint), :code, :name, :autoJournalType, :useYn, now(), now()) ' +
          'RETURNING voucher_type_id AS "voucherTypeId"',
        {
          accountItemId: String(data['accountItemId']).trim(),
          code: String(data['code']),
          name: String(data['name']),
          autoJournalType,
          useYn: String(data['useYn']),
        },
      );
      return rows[0];
    });
  }

  @Patch('/voucher-types/:voucherTypeId')
  async updateVoucherType(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const voucherTypeId = req.params['voucherTypeId'];
    if (!isIntegerValue(voucherTypeId)) {
      throw invalid('전표 유형 ID 형식이 올바르지 않습니다.');
    }
    const data = checks.inputOf(req.body);
    if (!isBlank(data['accountItemId']) && !isIntegerValue(data['accountItemId'])) {
      throw invalid('계정과목 형식이 올바르지 않습니다.');
    }
    if (!isBlank(data['useYn']) && !USE_YN.includes(String(data['useYn']))) {
      throw invalid('사용 여부가 올바르지 않습니다.');
    }
    const hasAuto = data['autoJournalType'] !== undefined;
    const autoJournalType = isBlank(data['autoJournalType']) ? null : String(data['autoJournalType']);
    if (autoJournalType !== null && autoJournalType.length > 100) {
      throw invalid('자동분개 유형은 100자 이하여야 합니다.');
    }
    const accountItemId = isBlank(data['accountItemId']) ? null : String(data['accountItemId']).trim();
    const useYn = isBlank(data['useYn']) ? null : String(data['useYn']);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT voucher_type_id FROM voucher_type WHERE voucher_type_id = CAST(:id AS bigint)',
        { id: voucherTypeId.trim() },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'VOUCHER_TYPE_NOT_FOUND', '전표 유형이 존재하지 않습니다.');
      }
      if (accountItemId !== null) {
        const accounts = await db.query(
          'SELECT account_item_id FROM account_item WHERE account_item_id = CAST(:accountItemId AS bigint)',
          { accountItemId },
        );
        if (accounts.length === 0) {
          throw new ApiError(404, 'ACCOUNT_ITEM_NOT_FOUND', '등록되지 않은 계정과목입니다.');
        }
      }
      await db.execute(
        'UPDATE voucher_type SET ' +
          'account_item_id = COALESCE(CAST(:accountItemId AS bigint), account_item_id), ' +
          'auto_journal_type = CASE WHEN CAST(:hasAuto AS boolean) THEN CAST(:autoJournalType AS varchar) ELSE auto_journal_type END, ' +
          'use_yn = COALESCE(CAST(:useYn AS varchar), use_yn), ' +
          'updated_at = now() ' +
          'WHERE voucher_type_id = CAST(:id AS bigint)',
        { id: voucherTypeId.trim(), accountItemId, hasAuto: hasAuto ? 'true' : 'false', autoJournalType, useYn },
      );
      const rows = await db.query(
        'SELECT voucher_type_id AS "voucherTypeId" FROM voucher_type WHERE voucher_type_id = CAST(:id AS bigint)',
        { id: voucherTypeId.trim() },
      );
      return rows[0];
    });
  }

  @Get('/voucher-types')
  async listVoucherTypes(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const { page, size } = pagingOf(query);
    return transaction(async (db) => {
      const items = await db.query(
        'SELECT voucher_type_id AS "voucherTypeId", account_item_id AS "accountItemId", code AS "code", name AS "name", ' +
          'auto_journal_type AS "autoJournalType", use_yn AS "useYn" ' +
          'FROM voucher_type ORDER BY code, voucher_type_id ' +
          'LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { size, offset: page * size },
      );
      const counts = await db.query('SELECT COUNT(*) AS "total" FROM voucher_type', {});
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }
}

