import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  TextInput,
  NumberInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const STATEMENT_TYPES: [string, string][] = [
  ['잔액시산표', '잔액시산표'],
  ['일·월계표', '일·월계표'],
  ['재무상태표', '재무상태표'],
  ['손익계산서', '손익계산서'],
];
const USE_YN: [string, string][] = [
  ['사용', '사용'],
  ['미사용', '미사용'],
];
const SIZE = 10;

export default function FnSfr00602Page({ role, notify }: PageProps) {
  const [statementType, setStatementType] = useState('');
  const [formPage, setFormPage] = useState(0);
  const [voucherPage, setVoucherPage] = useState(0);
  const [drawer, setDrawer] = useState<'' | 'form' | 'voucher' | 'edit'>('');
  const [editRow, setEditRow] = useState<Row | undefined>(undefined);
  const [formDraft, setFormDraft] = useState<Row>({ useYn: '사용' });
  const [voucherDraft, setVoucherDraft] = useState<Row>({ useYn: '사용' });
  const [editDraft, setEditDraft] = useState<Row>({});

  const forms = useData<Page>(
    () => call<Page>('GET', '/financial-statement-forms', role, undefined, { statementType, page: formPage, size: SIZE }),
    [statementType, formPage, role],
  );
  const vouchers = useData<Page>(
    () => call<Page>('GET', '/voucher-types', role, undefined, { page: voucherPage, size: SIZE }),
    [voucherPage, role],
  );

  function close() {
    setDrawer('');
    setEditRow(undefined);
  }

  function openEdit(row: Row) {
    setEditRow(row);
    setEditDraft({
      accountItemId: row['accountItemId'],
      autoJournalType: row['autoJournalType'] ?? '',
      useYn: row['useYn'],
    });
    setDrawer('edit');
  }

  const formColumns: Column[] = [
    { key: 'statementType', label: '재무제표 종류' },
    { key: 'itemName', label: '양식 구성 항목명' },
    { key: 'accountItemId', label: '계정과목', render: (r) => <RefName table="account_item" role={role} value={r['accountItemId']} /> },
    { key: 'sortOrder', label: '표시 순서', render: (r) => <Num2 value={r['sortOrder']} /> },
    { key: 'useYn', label: '사용 여부', render: (r) => <Badge value={r['useYn']} /> },
  ];

  const voucherColumns: Column[] = [
    { key: 'code', label: '전표유형 코드' },
    { key: 'name', label: '전표유형명' },
    { key: 'accountItemId', label: '계정과목', render: (r) => <RefName table="account_item" role={role} value={r['accountItemId']} /> },
    { key: 'autoJournalType', label: '자동분개 유형' },
    { key: 'useYn', label: '사용 여부', render: (r) => <Badge value={r['useYn']} /> },
  ];

  async function submitForm() {
    if (!formDraft['statementType'] || !formDraft['accountItemId'] || !formDraft['itemName'] || !formDraft['useYn']) {
      throw new Error('재무제표 종류, 계정과목, 항목명, 사용 여부를 모두 입력하세요.');
    }
    await call('POST', '/financial-statement-forms', role, formDraft);
    notify('재무제표 양식을 등록했습니다.');
    setFormDraft({ useYn: '사용' });
    close();
    forms.reload();
  }

  async function submitVoucher() {
    if (!voucherDraft['accountItemId'] || !voucherDraft['code'] || !voucherDraft['name'] || !voucherDraft['useYn']) {
      throw new Error('계정과목, 전표유형 코드, 전표유형명, 사용 여부를 모두 입력하세요.');
    }
    await call('POST', '/voucher-types', role, voucherDraft);
    notify('전표 유형을 등록했습니다.');
    setVoucherDraft({ useYn: '사용' });
    close();
    vouchers.reload();
  }

  async function submitEdit() {
    if (!editRow) {
      return;
    }
    await call('PATCH', '/voucher-types/' + String(editRow['voucherTypeId']), role, editDraft);
    notify('전표유형 설정을 수정했습니다.');
    close();
    vouchers.reload();
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>설정 현황</h2>
        <Tiles
          items={[
            ['재무제표 양식 항목', forms.data ? forms.data.total : 0],
            ['전표 유형', vouchers.data ? vouchers.data.total : 0],
          ]}
        />
      </section>

      <section className="box span-6">
        <h2>재무제표 양식</h2>
        <Filters
          onSearch={() => setFormPage(0)}
          onReset={() => {
            setStatementType('');
            setFormPage(0);
          }}
        >
          <Field label="재무제표 종류">
            <Select value={statementType} onChange={setStatementType} options={STATEMENT_TYPES} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={forms.data ? forms.data.total : 0}>
          <button type="button" onClick={() => setDrawer('form')}>양식 항목 등록</button>
        </Band>
        {forms.error ? <ErrorText text={forms.error} /> : null}
        <DataTable columns={formColumns} rows={forms.data ? forms.data.items : []} empty="등록된 양식 항목이 없습니다." />
        <Pager page={formPage} size={SIZE} total={forms.data ? forms.data.total : 0} onPage={setFormPage} />
      </section>

      <section className="box span-6">
        <h2>전표 유형 자동분개</h2>
        <Band total={vouchers.data ? vouchers.data.total : 0}>
          <button type="button" onClick={() => setDrawer('voucher')}>전표 유형 등록</button>
        </Band>
        {vouchers.error ? <ErrorText text={vouchers.error} /> : null}
        <DataTable
          columns={voucherColumns}
          rows={vouchers.data ? vouchers.data.items : []}
          onRowClick={openEdit}
          empty="등록된 전표 유형이 없습니다."
        />
        <Pager page={voucherPage} size={SIZE} total={vouchers.data ? vouchers.data.total : 0} onPage={setVoucherPage} />
      </section>

      {drawer === 'form' ? (
        <Drawer title="재무제표 양식 항목 등록" onClose={close}>
          <Form onSubmit={submitForm} submit="등록">
            <Field label="재무제표 종류" required>
              <Select
                value={formDraft['statementType']}
                onChange={(v) => setFormDraft({ ...formDraft, statementType: v })}
                options={STATEMENT_TYPES}
              />
            </Field>
            <Field label="계정과목" required>
              <LookupSelect
                table="account_item"
                role={role}
                value={formDraft['accountItemId']}
                onChange={(v) => setFormDraft({ ...formDraft, accountItemId: v })}
              />
            </Field>
            <Field label="양식 구성 항목명" required>
              <TextInput value={formDraft['itemName']} onChange={(v) => setFormDraft({ ...formDraft, itemName: v })} />
            </Field>
            <Field label="표시 순서">
              <NumberInput value={formDraft['sortOrder']} onChange={(v) => setFormDraft({ ...formDraft, sortOrder: v })} />
            </Field>
            <Field label="사용 여부" required>
              <Select value={formDraft['useYn']} onChange={(v) => setFormDraft({ ...formDraft, useYn: v })} options={USE_YN} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {drawer === 'voucher' ? (
        <Drawer title="전표 유형 등록" onClose={close}>
          <Form onSubmit={submitVoucher} submit="등록">
            <Field label="계정과목" required>
              <LookupSelect
                table="account_item"
                role={role}
                value={voucherDraft['accountItemId']}
                onChange={(v) => setVoucherDraft({ ...voucherDraft, accountItemId: v })}
              />
            </Field>
            <Field label="전표유형 코드" required>
              <TextInput value={voucherDraft['code']} onChange={(v) => setVoucherDraft({ ...voucherDraft, code: v })} />
            </Field>
            <Field label="전표유형명" required>
              <TextInput value={voucherDraft['name']} onChange={(v) => setVoucherDraft({ ...voucherDraft, name: v })} />
            </Field>
            <Field label="자동분개 유형">
              <TextInput
                value={voucherDraft['autoJournalType']}
                onChange={(v) => setVoucherDraft({ ...voucherDraft, autoJournalType: v })}
              />
            </Field>
            <Field label="사용 여부" required>
              <Select
                value={voucherDraft['useYn']}
                onChange={(v) => setVoucherDraft({ ...voucherDraft, useYn: v })}
                options={USE_YN}
              />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {drawer === 'edit' && editRow ? (
        <Drawer title="전표유형 자동분개 설정 수정" onClose={close}>
          <Pairs
            items={[
              ['전표유형 코드', String(editRow['code'] ?? '')],
              ['전표유형명', String(editRow['name'] ?? '')],
            ]}
          />
          <Form onSubmit={submitEdit} submit="수정">
            <Field label="계정과목">
              <LookupSelect
                table="account_item"
                role={role}
                value={editDraft['accountItemId']}
                onChange={(v) => setEditDraft({ ...editDraft, accountItemId: v })}
              />
            </Field>
            <Field label="자동분개 유형">
              <TextInput
                value={editDraft['autoJournalType']}
                onChange={(v) => setEditDraft({ ...editDraft, autoJournalType: v })}
              />
            </Field>
            <Field label="사용 여부">
              <Select value={editDraft['useYn']} onChange={(v) => setEditDraft({ ...editDraft, useYn: v })} options={USE_YN} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}

function Num2({ value }: { value: unknown }) {
  return <span>{value === null || value === undefined ? '' : String(value)}</span>;
}
